class Solution:
    def minimumDifference(self, nums: List[int], k: int) -> int:
        best = float('inf')
        ors = set()
        for x in nums:
            new_set = {v | x for v in ors}
            new_set.add(x)
            for v in new_set:
                d = abs(k - v)
                if d < best:
                    best = d
            ors = new_set
            if best == 0:
                return 0
        return best
