        nums = sorted(nums, reverse=True)
    elif mode == 2:
        nums = [nums[0]] * n
    k = draw(st.one_of(st.integers(1, 32), st.integers(1, 10**9)))
    return f"{json.dumps(nums)}\n{json.dumps(k)}\n"

